#include <HBEngine/Bridge.hpp>
#include <cassert>
#include <iostream>
#include <limits>
int main(){using namespace hb;Vec2 p,raw;int cases=0;for(const auto size: {Vec2{1280,720},Vec2{1600,900},Vec2{1024,768},Vec2{1920,1080},Vec2{1280,1024},Vec2{2560,1440},Vec2{3840,2160},Vec2{3440,1440},Vec2{1080,1920},Vec2{800,600}}){const float scale=std::min(size.x/1280.f,size.y/720.f);for(const auto point:{Vec2{0,0},Vec2{760,463.67f},Vec2{1100,463.67f},Vec2{640,360}}){bridgeInput["pointer"]={{"valid",true},{"inside",true},{"position",Vec2{point.x*scale,point.y*scale}},{"size",size}};assert(Input::GetMousePositionForCanvas({1280,720},p));assert(std::abs(p.x-point.x)<.001&&std::abs(p.y-point.y)<.001);assert(Input::GetMousePosition(raw));assert(raw.x==point.x*scale&&raw.y==point.y*scale);cases++;}}for(const auto size:{Vec2{0,0},Vec2{-1,720},Vec2{std::numeric_limits<float>::infinity(),720}}){bool rejected=false;try{Input::GetMousePositionForCanvas(size,p);}catch(...){rejected=true;}assert(rejected);cases++;}bridgeInput["pointer"]["inside"]=false;assert(!Input::GetMousePositionForCanvas({1280,720},p));bridgeInput["pointer"]={{"valid",false}};assert(!Input::GetMousePositionForCanvas({1280,720},p));std::cout<<"canvas input coordinates, raw API preservation, aspect ratios and invalid guards PASS "<<cases+2<<"\n";}
